import io.qameta.allure.Allure;
import io.qameta.allure.Attachment;
import io.qameta.allure.model.Status;

public class APITestAttachments {

    @Test
    public void testAPIWithAttachments() {
        Allure.step("Send API request", () -> {
            // Prepare request
            String requestBody = "{\"amount\":1000,\"currency\":\"USD\"}";

            // Attach request
            Allure.attachment("Request Body", requestBody);

            // Execute
            Response response = client.post("/api/payment", requestBody);

            // Attach response
            Allure.attachment("Response Body", response.getBody());
            Allure.attachment("Response Headers", response.getHeaders().toString());
            Allure.attachment("Response Time", response.getTime() + "ms");

            // Conditional attachments on failure
            if (response.getStatus() != 200) {
                Allure.attachment("Error Details", response.getErrorBody());
                Allure.step("Test failed - see attachments", Status.FAILED);
            }

            assertEquals(200, response.getStatus());
        });
    }

    // Method-based attachment
    @Attachment(value = "Request to {endpoint}", type = "application/json")
    public String attachRequest(String endpoint, String payload) {
        return payload;
    }

    // Python example
    @allure.attach.file("response.json", name="API Response", attachment_type=allure.attachment_type.JSON)
    def test_with_file_attachment():
        pass
}

// Python example with dynamic attachment
with allure.step("Send API request"):
    response = requests.post(url, json=payload)
    allure.attach(response.text, "Response Body", allure.attachment_type.JSON)
    allure.attach(str(response.headers), "Response Headers", allure.attachment_type.TEXT)

import io.restassured.RestAssured;
import io.restassured.filter.Filter;
import io.restassured.filter.FilterContext;
import io.restassured.response.Response;
import io.restassured.specification.FilterableRequestSpecification;
import io.restassured.specification.FilterableResponseSpecification;
import io.qameta.allure.Allure;

public class AllureRestAssuredFilter implements Filter {

    @Override
    public Response filter(FilterableRequestSpecification requestSpec,
                          FilterableResponseSpecification responseSpec,
                          FilterContext ctx) {
        // Attach request
        Allure.attachment("Request Method", requestSpec.getMethod());
        Allure.attachment("Request URI", requestSpec.getURI());
        Allure.attachment("Request Headers", requestSpec.getHeaders().toString());

        if (requestSpec.getBody() != null) {
            Allure.attachment("Request Body", requestSpec.getBody().toString());
        }

        // Execute request
        Response response = ctx.next(requestSpec, responseSpec);

        // Attach response
        Allure.attachment("Response Status", response.getStatusCode() + " " + response.getStatusLine());
        Allure.attachment("Response Headers", response.getHeaders().toString());
        Allure.attachment("Response Body", response.getBody().asString());
        Allure.attachment("Response Time", response.getTime() + "ms");

        return response;
    }
}

// Usage
RestAssured.filters(new AllureRestAssuredFilter());

import io.qameta.allure.Attachment;
import org.openqa.selenium.OutputType;
import org.openqa.selenium.TakesScreenshot;
import org.openqa.selenium.WebDriver;

public class ScreenshotUtils {

    @Attachment(value = "Page screenshot", type = "image/png")
    public static byte[] takeScreenshot(WebDriver driver) {
        return ((TakesScreenshot) driver).getScreenshotAs(OutputType.BYTES);
    }

    @Attachment(value = "Failure screenshot: {name}", type = "image/png")
    public static byte[] takeFailureScreenshot(WebDriver driver, String name) {
        return ((TakesScreenshot) driver).getScreenshotAs(OutputType.BYTES);
    }

    // Test with automatic screenshot on failure
    @Test
    public void testWithScreenshotOnFailure() {
        try {
            // Test steps
            driver.findElement(By.id("submit")).click();
        } catch (Exception e) {
            takeFailureScreenshot(driver, "submit-button-failure");
            throw e;
        }
    }
}

// JUnit extension for automatic screenshots
public class ScreenshotExtension implements TestWatcher {
    @Override
    public void testFailed(ExtensionContext context, Throwable cause) {
        WebDriver driver = getDriverFromContext(context);
        if (driver != null) {
            ScreenshotUtils.takeFailureScreenshot(driver, 
                context.getDisplayName().replace(" ", "-"));
        }
    }
}

// Python example with pytest
@pytest.fixture
def take_screenshot(request, driver):
    def fin():
        if request.node.rep_call.failed:
            allure.attach(driver.get_screenshot_as_png(), 
                         name="screenshot", 
                         attachment_type=allure.attachment_type.PNG)
    request.addfinalizer(fin)

content.explanation:
**Always capture on failure**: Screenshots are most valuable when tests fail.

**Capture strategies**:

| Strategy | When | Storage Impact | Value |
|----------|------|----------------|-------|
| On failure only | Test fails | Low | High |
| Every step | All tests | High | Medium |
| Key checkpoints | Critical points | Medium | High |
| Video recording | Complex flows | Very high | Very high |

**Implementation patterns**:

1. **Test Watcher/Listener**:
```java
// Automatically capture on test failure
@Override
public void testFailed(TestFailure failure) {
    captureScreenshot();
}
```

2. **Aspect-Oriented Programming**:
```java
@Around("@annotation(CaptureScreenshot)")
public void around(ProceedingJoinPoint joinPoint) {
    try {
        joinPoint.proceed();
    } catch (Throwable t) {
        captureScreenshot();
        throw t;
    }
}
```

3. **Manual at critical points**:
```java
Allure.step("Verify payment confirmation", () -> {
    // Verification
    if (failed) {
        Allure.attachment("Failure Screen", screenshot());
    }
});
```

**Best Practice**: Combine automatic on-failure capture with strategic manual captures at critical verification points.

