import io.qameta.allure.Allure;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;

public class LogAttachments {

    @Test
    public void testWithLogCapture() {
        // Capture logs during test
        ByteArrayOutputStream logStream = new ByteArrayOutputStream();
        PrintStream originalOut = System.out;
        System.setOut(new PrintStream(logStream));

        try {
            // Test execution that generates logs
            runTestWithLogging();

        } finally {
            // Restore original output
            System.setOut(originalOut);

            // Attach captured logs
            Allure.attachment("Test Logs", logStream.toString());
        }
    }

    // Attach thread dumps on timeout
    @Test(timeout = 5000)
    public void testWithThreadDumpOnTimeout() {
        try {
            // Long-running test
            Thread.sleep(10000);
        } catch (InterruptedException e) {
            // On timeout, attach thread dump
            Allure.attachment("Thread Dump", getThreadDump());
        }
    }

    private String getThreadDump() {
        StringBuilder dump = new StringBuilder();
        for (Thread thread : Thread.getAllStackTraces().keySet()) {
            dump.append(thread.toString()).append("\n");
            for (StackTraceElement element : thread.getStackTrace()) {
                dump.append("  ").append(element).append("\n");
            }
        }
        return dump.toString();
    }
}

// Python example with log capture
import logging
from io import StringIO

@allure.step("Test with log capture")
def test_with_logs():
    log_stream = StringIO()
    handler = logging.StreamHandler(log_stream)
    logging.getLogger().addHandler(handler)

    try:
        # Test code
        logging.info("Starting test")
        # ...
    finally:
        logging.getLogger().removeHandler(handler)
        allure.attach(log_stream.getvalue(), "Test Logs", allure.attachment_type.TEXT)

content.explanation:
For performance tests or memory-sensitive tests, Allure can capture diagnostic data.

**Performance Metrics**:

```java
@Attachment(value = "Response Time Distribution", type = "text/csv")
public String attachResponseTimes(List<Long> times) {
    StringBuilder csv = new StringBuilder("request,time_ms\n");
    for (int i = 0; i < times.size(); i++) {
        csv.append(i).append(",").append(times.get(i)).append("\n");
    }
    return csv.toString();
}
```

**Memory Usage**:

```java
@Attachment(value = "Memory Usage", type = "application/json")
public String attachMemoryUsage() {
    Runtime runtime = Runtime.getRuntime();
    return String.format(
        "{\"total\":%d,\"free\":%d,\"max\":%d,\"used\":%d}",
        runtime.totalMemory(),
        runtime.freeMemory(),
        runtime.maxMemory(),
        runtime.totalMemory() - runtime.freeMemory()
    );
}
```

**Database State**:

```java
@Attachment(value = "Database State Before Test", type = "application/json")
public String attachDbState(Connection conn, String query) {
    // Execute query and capture results
    // Convert to JSON or CSV
    return results;
}
```

**Network Diagnostics**:

```java
@Attachment(value = "Network Trace", type = "text/plain")
public String attachNetworkTrace() {
    // Capture netstat or connection info
    return executeCommand("netstat -an");
}
```

**Best Practice**: Attach diagnostics only when relevant—too many attachments slow down report generation and storage.

