import com.aventstack.extentreports.ExtentReports;
import com.aventstack.extentreports.ExtentTest;
import com.aventstack.extentreports.Status;
import org.junit.jupiter.api.extension.*;
import java.lang.reflect.Method;

public class ExtentJUnit5Extension implements 
    BeforeAllCallback, 
    AfterAllCallback,
    BeforeEachCallback, 
    AfterEachCallback,
    TestWatcher {

    private static ExtentReports extent = ExtentManager.getInstance();
    private static ThreadLocal<ExtentTest> test = new ThreadLocal<>();

    @Override
    public void beforeAll(ExtensionContext context) {
        // Not needed per test
    }

    @Override
    public void beforeEach(ExtensionContext context) {
        Method method = context.getRequiredTestMethod();
        ExtentTest extentTest = extent.createTest(
            context.getDisplayName()
        );

        // Add tags/categories
        if (method.isAnnotationPresent(Tag.class)) {
            Tag tag = method.getAnnotation(Tag.class);
            extentTest.assignCategory(tag.value());
        }

        test.set(extentTest);
    }

    @Override
    public void afterEach(ExtensionContext context) {
        // Test already logged via TestWatcher
    }

    @Override
    public void afterAll(ExtensionContext context) {
        extent.flush();
    }

    // TestWatcher methods
    @Override
    public void testSuccessful(ExtensionContext context) {
        test.get().log(Status.PASS, "Test passed");
    }

    @Override
    public void testFailed(ExtensionContext context, Throwable cause) {
        test.get().log(Status.FAIL, "Test failed: " + cause.getMessage());
        test.get().log(Status.FAIL, cause);
    }

    @Override
    public void testAborted(ExtensionContext context, Throwable cause) {
        test.get().log(Status.SKIP, "Test aborted: " + cause.getMessage());
    }

    @Override
    public void testDisabled(ExtensionContext context, Optional<String> reason) {
        test.get().log(Status.SKIP, "Test disabled: " + reason.orElse("No reason"));
    }
}
