import com.aventstack.extentreports.Status;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;

public class APITestWithAttachments {
    private static ExtentReports extent = ExtentManager.getInstance();

    @Test
    public void testPaymentAPI() {
        ExtentTest test = extent.createTest("Payment API Test");

        try {
            // Step 1: Prepare request
            test.log(Status.INFO, "Creating payment request");
            PaymentRequest request = PaymentRequest.builder()
                .amount(1000)
                .currency("USD")
                .card("4111111111111111")
                .build();

            // Attach formatted request
            Gson gson = new GsonBuilder().setPrettyPrinting().create();
            String requestJson = gson.toJson(request);
            test.log(Status.INFO, "Request Payload:");
            test.log(Status.INFO, "<pre>" + requestJson + "</pre>");

            // Step 2: Execute API call
            test.log(Status.INFO, "Sending request to /api/payments");
            Response response = client.post("/api/payments", request);

            // Attach response details
            test.log(Status.INFO, "Status Code: " + response.getStatusCode());
            test.log(Status.INFO, "Response Time: " + response.getTime() + "ms");

            // Attach formatted response
            String responseJson = gson.toJson(response.getBody());
            test.log(Status.INFO, "Response Payload:");
            test.log(Status.INFO, "<pre>" + responseJson + "</pre>");

            // Attach headers
            test.log(Status.INFO, "Response Headers:");
            response.getHeaders().forEach((key, value) -> {
                test.log(Status.INFO, key + ": " + value);
            });

            // Step 3: Assertions
            Assert.assertEquals(response.getStatusCode(), 200);
            Assert.assertEquals(response.getBody().getStatus(), "COMPLETED");

            test.log(Status.PASS, "Payment test passed");

        } catch (AssertionError e) {
            test.log(Status.FAIL, "Assertion failed: " + e.getMessage());
            test.log(Status.FAIL, e);
            throw e;
        } catch (Exception e) {
            test.log(Status.FAIL, "Exception: " + e.getMessage());
            test.log(Status.FAIL, e);
            throw e;
        } finally {
            extent.flush();
        }
    }
}

// Helper method for JSON attachment
private void attachJson(ExtentTest test, String name, Object data) {
    Gson gson = new GsonBuilder().setPrettyPrinting().create();
    String json = gson.toJson(data);
    test.log(Status.INFO, "<details><summary>" + name + "</summary>");
    test.log(Status.INFO, "<pre>" + json + "</pre>");
