**Method 4: Before/After Diff Visualization**:

```java
import com.github.difflib.DiffUtils;
import com.github.difflib.patch.Patch;

public void attachJsonDiff(ExtentTest test, String expected, String actual) {
    Patch<String> patch = DiffUtils.diffInline(
        Arrays.asList(expected.split("\\n")),
        Arrays.asList(actual.split("\\n"))
    );

    StringBuilder diff = new StringBuilder("<pre>\n");
    patch.getDeltas().forEach(delta -> {
        switch (delta.getType()) {
            case INSERT:
                diff.append("<span style='color:green'>+ ").append(delta.getTarget()).append("</span>\n");
                break;
            case DELETE:
                diff.append("<span style='color:red'>- ").append(delta.getSource()).append("</span>\n");
                break;
            case CHANGE:
                diff.append("<span style='color:orange'>~ ").append(delta.getSource()).append(" → ").append(delta.getTarget()).append("</span>\n");
                break;
        }
    });
    diff.append("</pre>");

    test.log(Status.INFO, "Expected vs Actual Diff:");
    test.log(Status.INFO, diff.toString());
}
