import javax.imageio.ImageIO;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.File;

public class APIScreenshotGenerator {

    public static String generateResponseScreenshot(Response response, String testName) {
        // Create image
        int width = 800;
        int height = 600;
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = image.createGraphics();

        // Background
        g.setColor(response.getStatus() == 200 ? Color.WHITE : new Color(255, 240, 240));
        g.fillRect(0, 0, width, height);

        // Title
        g.setColor(Color.BLACK);
        g.setFont(new Font("Monospaced", Font.BOLD, 16));
        g.drawString("API Response: " + testName, 20, 30);

        // Status line
        g.setFont(new Font("Monospaced", Font.PLAIN, 14));
        g.setColor(response.getStatus() == 200 ? new Color(0, 128, 0) : Color.RED);
        g.drawString("Status: " + response.getStatus() + " " + response.getMessage(), 20, 60);

        // Time
        g.setColor(Color.BLUE);
        g.drawString("Time: " + response.getTime() + "ms", 20, 80);

        // Headers
        g.setColor(Color.BLACK);
        g.setFont(new Font("Monospaced", Font.BOLD, 12));
        g.drawString("Headers:", 20, 110);

        g.setFont(new Font("Monospaced", Font.PLAIN, 12));
        int y = 130;
        for (Map.Entry<String, String> header : response.getHeaders().entrySet()) {
            g.drawString(header.getKey() + ": " + header.getValue(), 30, y);
            y += 20;
            if (y > height - 100) break;
        }

        // Body preview
        g.setFont(new Font("Monospaced", Font.BOLD, 12));
        g.drawString("Body (preview):", 20, y + 10);

        g.setFont(new Font("Monospaced", Font.PLAIN, 10));
        String body = response.getBody();
        if (body.length() > 500) {
            body = body.substring(0, 500) + "...";
        }

        String[] lines = body.split("\\n");
        y += 30;
        for (String line : lines) {
            if (y > height - 50) {
                g.drawString("...", 30, y);
                break;
            }
            g.drawString(line, 30, y);
            y += 15;
        }

        g.dispose();

        // Save image
        String filename = "screenshots/" + testName + "_" + System.currentTimeMillis() + ".png";
        try {
            File file = new File(filename);
            file.getParentFile().mkdirs();
            ImageIO.write(image, "png", file);
            return filename;
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    @Test
    public void testWithAPIScreenshot() {
        ExtentTest test = extent.createTest("Payment API - Visual Report");

        Response response = paymentAPI.submit(request);

        // Generate screenshot from response data
        String screenshotPath = generateResponseScreenshot(response, "payment-test");
        if (screenshotPath != null) {
            test.addScreenCaptureFromPath(screenshotPath, "API Response Visual");
        }

        Assert.assertEquals(200, response.getStatus());
    }
}

