Combine Extent Reports with Log4j for comprehensive logging that appears both in console and in HTML reports.

**Log4j Appender for Extent**:

```java
import org.apache.logging.log4j.core.Appender;
import org.apache.logging.log4j.core.Core;
import org.apache.logging.log4j.core.Filter;
import org.apache.logging.log4j.core.Layout;
import org.apache.logging.log4j.core.LogEvent;
import org.apache.logging.log4j.core.appender.AbstractAppender;
import org.apache.logging.log4j.core.config.plugins.Plugin;
import org.apache.logging.log4j.core.config.plugins.PluginAttribute;
import org.apache.logging.log4j.core.config.plugins.PluginElement;
import org.apache.logging.log4j.core.config.plugins.PluginFactory;

@Plugin(name = "ExtentAppender", category = Core.CATEGORY_NAME, elementType = Appender.ELEMENT_TYPE)
public class ExtentAppender extends AbstractAppender {
    private static ThreadLocal<ExtentTest> currentTest = new ThreadLocal<>();

    protected ExtentAppender(String name, Filter filter, Layout<?> layout) {
        super(name, filter, layout);
    }

    @PluginFactory
    public static ExtentAppender createAppender(
            @PluginAttribute("name") String name,
            @PluginElement("Filter") Filter filter,
            @PluginElement("Layout") Layout<?> layout) {
        return new ExtentAppender(name, filter, layout);
    }

    @Override
    public void append(LogEvent event) {
        ExtentTest test = currentTest.get();
        if (test != null) {
            String message = event.getMessage().getFormattedMessage();

            // Map log level to Extent status
            switch (event.getLevel().toString()) {
                case "ERROR":
                    test.log(Status.FAIL, message);
                    break;
                case "WARN":
                    test.log(Status.WARNING, message);
                    break;
                case "INFO":
                default:
                    test.log(Status.INFO, message);
                    break;
            }
        }
    }

    public static void setCurrentTest(ExtentTest test) {
        currentTest.set(test);
    }

    public static void clearCurrentTest() {
        currentTest.remove();
    }
}

