            Map<String, Object> test = new HashMap<>();
            test.put("name", result.name);
            test.put("status", result.status.toString().toLowerCase());
            test.put("duration", result.duration);
            test.put("request", formatJson(result.request));
            test.put("response", formatJson(result.response));
            test.put("logs", result.logs);
            test.put("error", result.error);
            testList.add(test);
        }
        context.setVariable("tests", testList);

        // Process template
        String html = templateEngine.process(template, context);

        // Write to file
        try (FileWriter writer = new FileWriter("custom-report.html")) {
            writer.write(html);
        }
    }

    private static String formatJson(String json) {
        try {
            ObjectMapper mapper = new ObjectMapper();
            Object obj = mapper.readValue(json, Object.class);
            return mapper.writerWithDefaultPrettyPrinter()
                .writeValueAsString(obj);
        } catch (Exception e) {
            return json;
        }
    }
}

