        ))].sort();

        const passData = dates.map(date => 
            this.data.tests.filter(t => 
                t.timestamp.startsWith(date) && t.status === 'PASS'
            ).length
        );

        const failData = dates.map(date => 
            this.data.tests.filter(t => 
                t.timestamp.startsWith(date) && t.status === 'FAIL'
            ).length
        );

        new Chart(ctx, {
            type: 'line',
            data: {
                labels: dates,
                datasets: [{
                    label: 'Passed',
                    data: passData,
                    borderColor: '#27ae60',
                    backgroundColor: 'rgba(39, 174, 96, 0.1)',
                    tension: 0.1
                }, {
                    label: 'Failed',
                    data: failData,
                    borderColor: '#c0392b',
                    backgroundColor: 'rgba(192, 57, 43, 0.1)',
                    tension: 0.1
                }]
            },
            options: {
                responsive: true,
                plugins: {
                    title: { display: true, text: 'Test Results Trend' }
                }
            }
        });
    }

    createCategoryChart() {
        const ctx = document.getElementById('categoryChart').getContext('2d');

        // Group by category
        const categories = {};
        this.data.tests.forEach(test => {
            const cat = test.category || 'Uncategorized';
            if (!categories[cat]) {
                categories[cat] = { total: 0, pass: 0, fail: 0 };
