        # Store in database
        self.store_metrics(report)

        # Send to dashboards
        self.update_dashboards(report)

        return report

// React component for metrics dashboard

import React, { useState, useEffect } from 'react';
import { Line, Bar, Gauge } from 'react-chartjs-2';

const MetricsDashboard = () => {
    const [metrics, setMetrics] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchMetrics();
        const interval = setInterval(fetchMetrics, 60000); // Update every minute
        return () => clearInterval(interval);
    }, []);

    const fetchMetrics = async () => {
        try {
            const response = await fetch('/api/metrics/current');
            const data = await response.json();
            setMetrics(data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch metrics:', error);
        }
    };

    if (loading) return <div>Loading metrics...</div>;

    return (
        <div className="dashboard">
            <div className="kpi-row">
                <Gauge
                    value={metrics.ddp}
                    min={0}
                    max={100}
                    thresholds={[85, 95, 98]}
                    label="DDP"
                />
                <Gauge
                    value={metrics.availability}
                    min={99.0}
                    max={100.0}
                    thresholds={[99.5, 99.9, 99.99]}
                    label="Availability"
                />
                <Gauge
                    value={metrics.flakiness}
                    min={0}
                    max={30}
                    reverse={true}
                    thresholds={[15, 8, 3]}
                    label="Flakiness %"
                />
            </div>

            <div className="chart-row">
                <Line
                    data={{
                        labels: metrics.dates,
                        datasets: [{
                            label: 'p95 Response Time (ms)',
                            data: metrics.p95Times,
                            borderColor: '#e67e22',
                            fill: false
                        }]
                    }}
                    options={{
                        responsive: true,
                        title: 'Response Time Trend'
                    }}
                />

                <Bar
                    data={{
                        labels: metrics.endpoints,
                        datasets: [{
                            label: 'Error Rate %',
                            data: metrics.errorRates,
                            backgroundColor: '#e74c3c'
                        }]
                    }}
                    options={{
                        responsive: true,
                        title: 'Error Rate by Endpoint'
                    }}
                />
            </div>

            <div className="alerts">
                {metrics.alerts.map(alert => (
                    <div key={alert.id} className={`alert alert-${alert.severity}`}>
                        {alert.message}
                    </div>
                ))}
            </div>
        </div>
    );
};

export default MetricsDashboard;

content.explanation:
Understanding REST constraints helps you test for architectural compliance, not just functional correctness.

**The Six REST Constraints:**

| Constraint | What It Means | Testing Implications |
|------------|---------------|----------------------|
| **Uniform Interface** | Consistent resource identification, manipulation | Test URL conventions, HTTP method usage, response formats |
| **Stateless** | Each request contains all info | Test with session dependencies, verify no server-side state |
| **Cacheable** | Responses labeled cacheable or not | Test Cache-Control headers, ETags, validation |
| **Client-Server** | Separation of concerns | Test API independently of UI |
| **Layered System** | Intermediaries (proxies, gateways) | Test through load balancers, verify headers preserved |
| **Code on Demand** (optional) | Executable code from server | Rarely used, test security implications |

**Testing RESTful Compliance:**

```java
// Testing uniform interface
@Test
public void testRESTfulDesign() {
    // Resource identification in URLs
    assertTrue(api.getUsers().getUrl().endsWith("/users"));
    assertTrue(api.getUser(123).getUrl().endsWith("/users/123"));

    // Manipulation through representations
    Response response = api.updateUser(123, userData);
    assertEquals(200, response.getStatus());

    // Self-descriptive messages
    assertNotNull(response.getHeader("Content-Type"));
    assertTrue(response.getHeader("Content-Type").contains("application/json"));

    // HATEOAS (Hypermedia as Engine of Application State)
    if (api.supportsHATEOAS()) {
        assertTrue(response.getBody().contains("_links"));
    }
}
```

**Common REST Anti-patterns to Test For:**
- Using GET to modify data
- Using POST for everything
- Ignoring proper status codes
- Inconsistent URL patterns (/getUser vs /users/123)
- Session state in server
- Missing cache headers

**Sample Interview Questions:**
1. "How would you test if an API truly follows REST principles?"
2. "What's the difference between REST and RESTful? How does testing differ?"
3. "How do you test HATEOAS compliance?"
4. "Design tests for a REST API that violates statelessness"
5. "How would you verify cache behavior in a REST API?"

