   @Test
   public void testConcurrentCartUpdates() throws InterruptedException {
       // Simulate 10 users updating same cart
       ExecutorService executor = Executors.newFixedThreadPool(10);
       CountDownLatch latch = new CountDownLatch(10);
       AtomicInteger successCount = new AtomicInteger();

       for (int i = 0; i < 10; i++) {
           final int itemId = i;
           executor.submit(() -> {
               try {
                   Response response = cartAPI.addItem(itemId, 1);
